from lib import *
L = lambda *a, **k: lesson(6, "A0", *a, **k)
L(1, "Котра година?", "Спитати, котра година, і назвати рівну годину.",
 "What time is it? — «Котра година?». Відповідь: It's + число + o'clock: It's five o'clock. O'clock кажуть лише про рівну годину. In the morning — вранці, in the evening — увечері, at night — уночі.",
 [W("time", "/taɪm/", "noun", "час", "What time is it?", "Котра година?"),
  W("o'clock", "/əˈklɒk/", "adverb", "рівно … година", "It's five o'clock.", "П'ята година."),
  W("now", "/naʊ/", "adverb", "зараз", "It's ten o'clock now.", "Зараз десята година."),
  W("today", "/təˈdeɪ/", "adverb", "сьогодні", "I'm here today.", "Я сьогодні тут."),
  W("morning", "/ˈmɔːnɪŋ/", "noun", "ранок", "Seven o'clock in the morning.", "Сьома година ранку."),
  W("evening", "/ˈiːvnɪŋ/", "noun", "вечір", "Eight o'clock in the evening.", "Восьма година вечора."),
  W("night", "/naɪt/", "noun", "ніч", "Two o'clock at night.", "Друга година ночі.")],
 [liu("thirty-eight", "Повторимо. Прослухайте. Яке це число?", ["38", "83", "18"], "Thirty-eight — 38."),
  mt([("time", "час"), ("now", "зараз"), ("today", "сьогодні"), ("o'clock", "рівно … година")], "Слова для розмови про час."),
  mt([("morning", "ранок"), ("evening", "вечір"), ("night", "ніч"), ("year", "рік")], "Частини доби."),
  liu("What time is it?", "Прослухайте. Що вас питають?", ["Котра година?", "Скільки це коштує?", "Який сьогодні день?"], "What time is it? — «Котра година?»"),
  liu("It's nine o'clock.", "Прослухайте. Котра година?", ["9:00", "5:00", "19:00"], "Nine o'clock — дев'ята година."),
  fb("It's three ___.", ["o'clock", "time", "years"], "Рівна година — o'clock."),
  fb("Seven o'clock ___ the morning.", ["in", "on", "at"], "In the morning, in the evening."),
  bs("Зараз шоста година.", ["It's", "six", "o'clock", "now"], ["time", "is"], "It's six o'clock now."),
  tr("Котра година?", ["What time is it", "What's the time"], "What time is it?"),
  li("What time is it?", "На годиннику 10:00. Що відповісти?", ["It's ten o'clock.", "It's ten years.", "I'm ten."], "It's ten o'clock.")])
L(2, "Пів на шосту", "Назвати час із половиною та чвертю.",
 "Half past six — 6:30, дослівно «половина після шостої». Українською кажуть «пів на сьому», англійською — рахують від години, що минула. Quarter past six — 6:15. Quarter to seven — 6:45, «чверть до сьомої».",
 [W("half past", "/ˌhɑːf ˈpɑːst/", "phrase", "пів години після", "It's half past six.", "Зараз пів на сьому (6:30)."),
  W("quarter", "/ˈkwɔːtə/", "noun", "чверть (15 хвилин)", "It's quarter past two.", "Зараз чверть на третю (2:15)."),
  W("past", "/pɑːst/", "preposition", "після (про час)", "Ten past five.", "Десять хвилин на шосту (5:10)."),
  W("to", "/tuː/", "preposition", "до (про час)", "Quarter to seven.", "За чверть сьома (6:45)."),
  W("minute", "/ˈmɪnɪt/", "noun", "хвилина", "Five minutes, please.", "П'ять хвилин, будь ласка."),
  W("hour", "/ˈaʊə/", "noun", "година (60 хвилин)", "Two hours.", "Дві години.")],
 [li("What time is it?", "Повторимо. На годиннику 4:00. Що відповісти?", ["It's four o'clock.", "It's forty.", "It's four years."], "It's four o'clock."),
  mt([("half past", "пів години після"), ("quarter", "чверть"), ("minute", "хвилина"), ("hour", "година")], "В hour літера h не вимовляється."),
  mcu("Котра година: half past six?", ["6:30", "5:30", "7:30"], "Half past six — половина після шостої: 6:30."),
  mcu("Котра година: quarter past two?", ["2:15", "2:45", "1:45"], "Past — після: чверть після другої, 2:15."),
  mcu("Котра година: quarter to seven?", ["6:45", "7:15", "7:45"], "To — до: чверть до сьомої, 6:45."),
  liu("It's half past nine.", "Прослухайте. Котра година?", ["9:30", "8:30", "9:15"], "Half past nine — 9:30."),
  fb("It's half ___ three.", ["past", "to", "o'clock"], "Половина — завжди half past."),
  mc("Як сказати 8:15?", ["quarter past eight", "quarter to eight", "half past eight"], "15 хвилин після восьмої — quarter past eight."),
  tr("пів на п'яту (4:30)", ["half past four", "It's half past four"], "4:30 — half past four."),
  li("What time is it?", "На годиннику 11:45. Що відповісти?", ["It's quarter to twelve.", "It's quarter past twelve.", "It's half past eleven."], "11:45 — чверть до дванадцятої: quarter to twelve.")])
L(3, "Відчинено чи зачинено?", "Спитати, коли працює магазин чи банк, і зрозуміти відповідь.",
 "Перед годиною ставлять at: at nine — о дев'ятій. From… to… — «з… до…»: from nine to five. When…? — «Коли…?». Про години роботи: The shop is open. The bank is closed.",
 [W("when", "/wen/", "adverb", "коли", "When is the bank open?", "Коли працює банк?"),
  W("open", "/ˈəʊpən/", "adjective", "відчинений", "The shop is open.", "Магазин відчинений."),
  W("closed", "/kləʊzd/", "adjective", "зачинений", "The bank is closed.", "Банк зачинений."),
  W("shop", "/ʃɒp/", "noun", "магазин", "The shop is open today.", "Магазин сьогодні працює."),
  W("bank", "/bæŋk/", "noun", "банк", "Where is the bank?", "Де банк?"),
  W("café", "/ˈkæfeɪ/", "noun", "кафе", "The café is next to the bank.", "Кафе біля банку."),
  W("at", "/æt/", "preposition", "о (про годину)", "At nine o'clock.", "О дев'ятій годині.")],
 [mcu("Повторимо. Котра година: half past seven?", ["7:30", "6:30", "7:15"], "Half past seven — 7:30."),
  mt([("open", "відчинений"), ("closed", "зачинений"), ("when", "коли"), ("shop", "магазин")], "Open і closed пишуть на дверях."),
  liu("The bank is closed today.", "Прослухайте. Що ви дізналися?", ["Банк сьогодні зачинений", "Банк сьогодні відчинений", "Банк біля кафе"], "Closed — зачинений."),
  fb("The café is open ___ eight o'clock.", ["at", "in", "on"], "Перед годиною — at."),
  fb("The shop is open from nine ___ six.", ["to", "at", "past"], "From nine to six — з дев'ятої до шостої."),
  liu("When is the shop open?", "Прослухайте. Що питає людина?", ["Коли працює магазин?", "Де магазин?", "Що це за магазин?"], "When — коли."),
  liu("It's open from ten to seven.", "Прослухайте. Коли відчинено?", ["З 10 до 7", "З 7 до 10", "З 10 до 6"], "From ten to seven."),
  bs("Банк сьогодні зачинений.", ["The", "bank", "is", "closed", "today"], ["open", "at"], "The bank is closed today."),
  tr("Магазин відчинений.", ["The shop is open"], "The shop is open."),
  li("Excuse me, when is the café open?", "Кафе відчиняється о восьмій. Що відповісти?", ["At eight o'clock.", "In eight o'clock.", "Eight pounds."], "О восьмій — at eight o'clock.")])
L(4, "Доброго ранку!", "Привітатися відповідно до часу доби й попрощатися до завтра.",
 "Вранці кажуть Good morning, удень Good afternoon, увечері Good evening. Good night — це не привітання, а прощання перед сном. See you tomorrow — «до завтра».",
 [W("good morning", "/ˌɡʊd ˈmɔːnɪŋ/", "phrase", "доброго ранку", "Good morning, Anna!", "Доброго ранку, Анно!"),
  W("afternoon", "/ˌɑːftəˈnuːn/", "noun", "день (після дванадцятої)", "Good afternoon!", "Добрий день!"),
  W("good evening", "/ˌɡʊd ˈiːvnɪŋ/", "phrase", "добрий вечір", "Good evening!", "Добрий вечір!"),
  W("good night", "/ˌɡʊd ˈnaɪt/", "phrase", "на добраніч", "Good night, Tom.", "На добраніч, Томе."),
  W("tomorrow", "/təˈmɒrəʊ/", "adverb", "завтра", "See you tomorrow.", "До завтра."),
  W("see you", "/ˈsiː juː/", "phrase", "до зустрічі", "See you!", "До зустрічі!"),
  W("early", "/ˈɜːli/", "adjective", "рано, ранній", "It's very early.", "Ще дуже рано."),
  W("late", "/leɪt/", "adjective", "пізно; той, що запізнився", "Sorry, I'm late.", "Вибачте, я запізнився.")],
 [fb("The shop is open ___ nine o'clock.", ["at", "in", "to"], "Перед годиною — at.", "Повторимо. Оберіть слово, якого бракує"),
  mt([("good morning", "доброго ранку"), ("good evening", "добрий вечір"), ("good night", "на добраніч"), ("see you", "до зустрічі")], "Good night — тільки на прощання."),
  mt([("tomorrow", "завтра"), ("today", "сьогодні"), ("early", "рано"), ("late", "пізно")], "Today — tomorrow, early — late."),
  mc("Зараз 8:00 ранку. Як привітатися?", ["Good morning!", "Good evening!", "Good night!"], "Вранці — Good morning."),
  mc("Зараз 15:00. Як привітатися?", ["Good afternoon!", "Good morning!", "Good night!"], "Після дванадцятої й до вечора — Good afternoon."),
  mc("Ви йдете спати. Що сказати?", ["Good night!", "Good evening!", "Good afternoon!"], "Перед сном — Good night."),
  liu("See you tomorrow!", "Прослухайте. Що каже людина?", ["До завтра", "До побачення назавжди", "Побачимося сьогодні"], "Tomorrow — завтра."),
  bs("Вибачте, я запізнився.", ["Sorry", "I'm", "late"], ["early", "is"], "Sorry — «вибачте». I'm late — «я запізнився»."),
  tr("До завтра.", ["See you tomorrow"], "See you tomorrow."),
  li("Good evening!", "Вас вітають увечері. Що відповісти?", ["Good evening!", "Good night!", "See you tomorrow!"], "На привітання відповідають тим самим: Good evening.")])
L(5, "О котрій поїзд?", "Спитати, о котрій щось починається, і домовитися про час.",
 "What time is…? — «О котрій…?»: What time is the train? Відповідь: At + час. Час за розкладом читають двома числами: 10:15 — ten fifteen, 7:40 — seven forty.",
 [W("train", "/treɪn/", "noun", "поїзд", "What time is the train?", "О котрій поїзд?"),
  W("bus", "/bʌs/", "noun", "автобус", "The bus is at ten.", "Автобус о десятій."),
  W("meeting", "/ˈmiːtɪŋ/", "noun", "зустріч, нарада", "The meeting is at two.", "Зустріч о другій."),
  W("lesson", "/ˈlesn/", "noun", "урок", "My lesson is at six.", "Мій урок о шостій."),
  W("breakfast", "/ˈbrekfəst/", "noun", "сніданок", "Breakfast is at eight.", "Сніданок о восьмій."),
  W("lunch", "/lʌntʃ/", "noun", "обід", "Lunch is at one.", "Обід о першій."),
  W("dinner", "/ˈdɪnə/", "noun", "вечеря", "Dinner is at seven.", "Вечеря о сьомій.")],
 [mc("Повторимо. Зараз 9:00 ранку. Як привітатися?", ["Good morning!", "Good night!", "Good evening!"], "Вранці — Good morning."),
  mt([("train", "поїзд"), ("bus", "автобус"), ("meeting", "зустріч"), ("lesson", "урок")], "Те, що має розклад."),
  mt([("breakfast", "сніданок"), ("lunch", "обід"), ("dinner", "вечеря"), ("time", "час")], "Три прийоми їжі за день."),
  liu("What time is the train?", "Прослухайте. Що питає людина?", ["О котрій поїзд?", "Де поїзд?", "Скільки коштує поїзд?"], "What time is…? — «О котрій…?»"),
  liu("The bus is at ten fifteen.", "Прослухайте. О котрій автобус?", ["10:15", "10:50", "15:10"], "Ten fifteen — 10:15."),
  mcu("Як прочитати час 7:40?", ["seven forty", "seven fourteen", "forty seven"], "Спочатку година, потім хвилини: seven forty."),
  fb("Breakfast is ___ half past seven.", ["at", "in", "on"], "Перед часом — at."),
  bs("О котрій зустріч?", ["What", "time", "is", "the", "meeting"], ["when", "at"], "What time is the meeting?"),
  tr("Обід о першій.", ["Lunch is at one", "Lunch is at one o'clock"], "Lunch is at one."),
  li("What time is dinner?", "Вечеря о сьомій тридцять. Що відповісти?", ["At half past seven.", "In seven thirty.", "Seven pounds thirty."], "At half past seven — о пів на восьму.")])
L(6, "Повторення: мій час", "Спитати й назвати час, години роботи та розклад.",
 "Нових слів немає. Повторюємо: What time is it?, o'clock, half past, quarter past і to, at, from… to…, open і closed, привітання за часом доби.",
 [],
 [li("What time is it?", "На годиннику 3:30. Що відповісти?", ["It's half past three.", "It's half past four.", "It's three o'clock."], "3:30 — half past three."),
  mcu("Котра година: quarter to ten?", ["9:45", "10:15", "10:45"], "Чверть до десятої — 9:45."),
  fb("The bank is open ___ nine to five.", ["from", "at", "in"], "From nine to five."),
  liu("The train is at six forty.", "Прослухайте. О котрій поїзд?", ["6:40", "6:14", "4:06"], "Six forty — 6:40."),
  tr("Котра година?", ["What time is it", "What's the time"], "What time is it?"),
  mc("Зараз 20:00. Ви заходите в ресторан. Як привітатися?", ["Good evening!", "Good night!", "Good morning!"], "Увечері вітаються Good evening. Good night — прощання."),
  bs("Магазин сьогодні зачинений.", ["The", "shop", "is", "closed", "today"], ["open", "tomorrow"], "The shop is closed today."),
  fb("Sorry, I'm ___. — No problem.", ["late", "early", "closed"], "Sorry, I'm late — вибачте, я запізнився."),
  li("What time is breakfast?", "Сніданок із сьомої до десятої. Що відповісти?", ["From seven to ten.", "At seven to ten pounds.", "It's ten years."], "From seven to ten."),
  li("See you tomorrow!", "З вами прощаються до завтра. Що відповісти?", ["See you! Bye!", "Good morning!", "Nice to meet you."], "See you! Bye!")],
 review=True)
